import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.rm68tLg1.js";const u=JSON.parse('{"title":"Why there is no runtime reflection","description":"","frontmatter":{},"headers":[],"relativePath":"learn/explanation/no-reflection.md","filePath":"learn/explanation/no-reflection.md","lastUpdated":1786299590000}'),r={name:"learn/explanation/no-reflection.md"};function i(s,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="why-there-is-no-runtime-reflection" tabindex="-1">Why there is no runtime reflection <a class="header-anchor" href="#why-there-is-no-runtime-reflection" aria-label="Permalink to &quot;Why there is no runtime reflection&quot;">​</a></h1><p>Most annotation-driven argument parsers read their annotations at startup: your program launches, the library reflects over your class, discovers the fields, and builds a parser in memory. Argot does the discovery at build time instead, and emits ordinary Kotlin.</p><h2 id="what-that-buys" tabindex="-1">What that buys <a class="header-anchor" href="#what-that-buys" aria-label="Permalink to &quot;What that buys&quot;">​</a></h2><p><strong>Mistakes surface while you compile.</strong> A duplicate option name, a positional in an impossible position, an unsupported parameter type — the processor reports these as compile errors with the offending parameter underlined. A reflective parser cannot know about any of them until the program runs, which usually means until a test runs, which sometimes means until a user runs it.</p><p><strong>Startup does no work.</strong> There is no classpath scan and no annotation parsing at launch. For a library about command-line programs this is not academic: CLIs are processes that start constantly, often in scripts and loops, and a parser that costs tens of milliseconds before <code>main</code> gets going is paying that on every invocation.</p><p><strong>Nothing is invisible to your tools.</strong> The generated parser is real Kotlin in your build directory. You can read it, step into it in a debugger, and see it in a stack trace. When something is wrong, the thing you are debugging is code rather than a library&#39;s model of your code.</p><p><strong>It survives being shrunk.</strong> Reflection makes your annotated classes reachable only through names, so R8, ProGuard and GraalVM native-image all need to be told to keep them. Argot&#39;s generated parser references your constructor directly, which is exactly the kind of edge a static analyser can follow. No keep rules, no reflection configuration.</p><p><strong>Two dependencies weigh nothing at runtime.</strong> <code>argot-core</code> and <code>argot-annotations</code> depend on the Kotlin standard library and nothing else. KSP and KotlinPoet are build-time only.</p><h2 id="what-it-costs" tabindex="-1">What it costs <a class="header-anchor" href="#what-it-costs" aria-label="Permalink to &quot;What it costs&quot;">​</a></h2><p><strong>A build plugin.</strong> Annotation-style users must apply KSP, and KSP is published against one specific Kotlin version. That makes Argot&#39;s Kotlin version part of your build&#39;s constraints rather than an implementation detail — which is why a Kotlin or KSP bump is a minor release for Argot, not a patch.</p><p><strong>Compile time, not startup time.</strong> The work does not vanish; it moves. For a handful of commands this is not measurable, but it is a real transfer rather than a free win.</p><p><strong>No dynamic declarations.</strong> You cannot build a command line from a config file read at startup, or add an option based on a runtime condition. Everything must be knowable at compile time. If that is what you need, Argot&#39;s delegate style gets you closer — you can conditionally read properties — but the declaration itself is still static.</p><p><strong>No custom converters in the annotation style.</strong> The processor picks a converter from the parameter&#39;s type, and there is no way to name one it has not been taught. A reflective library could accept a <code>KClass</code> and instantiate it; the processor would have to generate a reference to something it can resolve. Use the <a href="./../how-to/custom-converter">delegate style</a> when you need one.</p><h2 id="the-delegate-style-is-not-reflective-either" tabindex="-1">The delegate style is not reflective either <a class="header-anchor" href="#the-delegate-style-is-not-reflective-either" aria-label="Permalink to &quot;The delegate style is not reflective either&quot;">​</a></h2><p>&quot;No reflection&quot; is usually said only about annotation processing, so to be explicit: Kotlin&#39;s property delegates are a language feature, not a reflective one. <code>by option(...)</code> compiles to a field holding the delegate and a getter that calls it. The <code>KProperty</code> passed to <code>provideDelegate</code> carries the property&#39;s name, which is how a positional argument gets named after the property it is assigned to — but that is a compiler-provided object, not a runtime lookup of your class.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./two-styles">Two styles, one engine</a> for what the processor actually generates.</li><li><a href="./optionality">How optionality is inferred</a> for what the processor can and cannot see.</li></ul>',17)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
